/**
 * @file sog_to_ply.cpp
 * @brief SOG to PLY converter (for verification)
 * 
 * Converts SOG format back to PLY to verify data integrity
 */

#include <tinysog/tinysog.h>
#include <cuda_runtime.h>
#include <iostream>
#include <fstream>
#include <vector>
#include <cstring>
#include <cmath>
#include <filesystem>

bool write_ply(const std::string& file_path, const tinysog::GaussianData& data) {
    std::ofstream outfile(file_path, std::ios_base::binary);
    
    if (!outfile.good()) {
        std::cerr << "Failed to open output file: " << file_path << std::endl;
        return false;
    }
    
    // Write PLY header
    outfile << "ply\n";
    outfile << "format binary_little_endian 1.0\n";
    outfile << "comment generated by tinysog sog_to_ply\n";
    outfile << "element vertex " << data.count << "\n";
    
    outfile << "property float x\n";
    outfile << "property float y\n";
    outfile << "property float z\n";
    
    // SH DC coefficients
    outfile << "property float f_dc_0\n";
    outfile << "property float f_dc_1\n";
    outfile << "property float f_dc_2\n";
    
    // SH rest coefficients
    if (data.shN != nullptr) {
        for (int i = 0; i < data.sh_num_coeffs * 3; i++) {
            outfile << "property float f_rest_" << i << "\n";
        }
    }
    
    outfile << "property float opacity\n";
    outfile << "property float scale_0\n";
    outfile << "property float scale_1\n";
    outfile << "property float scale_2\n";
    outfile << "property float rot_0\n";
    outfile << "property float rot_1\n";
    outfile << "property float rot_2\n";
    outfile << "property float rot_3\n";
    
    outfile << "end_header\n";
    
    // Allocate host memory for data
    std::vector<float> host_means(data.count * 3);
    std::vector<float> host_sh0(data.count * 3);
    std::vector<float> host_shN;
    if (data.shN != nullptr) {
        host_shN.resize(data.count * data.sh_num_coeffs * 3);
    }
    std::vector<float> host_opacity(data.count);
    std::vector<float> host_scales(data.count * 3);
    std::vector<float> host_rotations(data.count * 4);
    
    // Copy from GPU/CPU to host
    if (data.is_cpu) {
        memcpy(host_means.data(), data.means, data.count * 3 * sizeof(float));
        memcpy(host_sh0.data(), data.sh0, data.count * 3 * sizeof(float));
        if (data.shN != nullptr) {
            memcpy(host_shN.data(), data.shN, data.count * data.sh_num_coeffs * 3 * sizeof(float));
        }
        memcpy(host_opacity.data(), data.opacity, data.count * sizeof(float));
        memcpy(host_scales.data(), data.scales, data.count * 3 * sizeof(float));
        memcpy(host_rotations.data(), data.rotations, data.count * 4 * sizeof(float));
    } else {
        cudaMemcpy(host_means.data(), data.means, data.count * 3 * sizeof(float), cudaMemcpyDeviceToHost);
        cudaMemcpy(host_sh0.data(), data.sh0, data.count * 3 * sizeof(float), cudaMemcpyDeviceToHost);
        if (data.shN != nullptr) {
            cudaMemcpy(host_shN.data(), data.shN, data.count * data.sh_num_coeffs * 3 * sizeof(float), cudaMemcpyDeviceToHost);
        }
        cudaMemcpy(host_opacity.data(), data.opacity, data.count * sizeof(float), cudaMemcpyDeviceToHost);
        cudaMemcpy(host_scales.data(), data.scales, data.count * 3 * sizeof(float), cudaMemcpyDeviceToHost);
        cudaMemcpy(host_rotations.data(), data.rotations, data.count * 4 * sizeof(float), cudaMemcpyDeviceToHost);
    }
    
    // Write binary data
    for (size_t i = 0; i < data.count; ++i) {
        // Position
        outfile.write(reinterpret_cast<const char*>(&host_means[i * 3 + 0]), sizeof(float));
        outfile.write(reinterpret_cast<const char*>(&host_means[i * 3 + 1]), sizeof(float));
        outfile.write(reinterpret_cast<const char*>(&host_means[i * 3 + 2]), sizeof(float));
        
        // SH DC
        outfile.write(reinterpret_cast<const char*>(&host_sh0[i * 3 + 0]), sizeof(float));
        outfile.write(reinterpret_cast<const char*>(&host_sh0[i * 3 + 1]), sizeof(float));
        outfile.write(reinterpret_cast<const char*>(&host_sh0[i * 3 + 2]), sizeof(float));
        
        // SH rest
        if (data.shN != nullptr) {
            for (int j = 0; j < data.sh_num_coeffs * 3; ++j) {
                outfile.write(reinterpret_cast<const char*>(&host_shN[i * data.sh_num_coeffs * 3 + j]), sizeof(float));
            }
        }
        
        // Opacity: convert from [0,1] back to logit space for PLY
        float opacity_01 = host_opacity[i];
        // Clamp to avoid log(0) or log(inf)
        opacity_01 = std::clamp(opacity_01, 0.0001f, 0.9999f);
        float opacity_logit = std::log(opacity_01 / (1.0f - opacity_01));
        outfile.write(reinterpret_cast<const char*>(&opacity_logit), sizeof(float));
        
        // Scale
        outfile.write(reinterpret_cast<const char*>(&host_scales[i * 3 + 0]), sizeof(float));
        outfile.write(reinterpret_cast<const char*>(&host_scales[i * 3 + 1]), sizeof(float));
        outfile.write(reinterpret_cast<const char*>(&host_scales[i * 3 + 2]), sizeof(float));
        
        // Rotation (quaternion is stored as [w,x,y,z] in tinysog, PLY also expects [w,x,y,z] as rot_0,1,2,3)
        outfile.write(reinterpret_cast<const char*>(&host_rotations[i * 4 + 0]), sizeof(float)); // w
        outfile.write(reinterpret_cast<const char*>(&host_rotations[i * 4 + 1]), sizeof(float)); // x
        outfile.write(reinterpret_cast<const char*>(&host_rotations[i * 4 + 2]), sizeof(float)); // y
        outfile.write(reinterpret_cast<const char*>(&host_rotations[i * 4 + 3]), sizeof(float)); // z
    }
    
    outfile.close();
    return true;
}

int main(int argc, char** argv) {
    std::cout << "=== TinySOG SOG to PLY Converter ===" << std::endl;
    std::cout << "TinySOG version: " << tinysog::get_version() << std::endl << std::endl;
    
    // Parse arguments
    if (argc != 2 && argc != 3) {
        std::cerr << "Usage: " << argv[0] << " <input.sog> [output.ply]" << std::endl;
        std::cerr << "Example: " << argv[0] << " test.sog output.ply" << std::endl;
        std::cerr << "If output is not specified, will use input filename with .ply extension" << std::endl;
        return 1;
    }
    
    std::string input_path = argv[1];
    std::string output_path;
    
    if (argc == 3) {
        output_path = argv[2];
    } else {
        // Auto-generate output path
        std::filesystem::path input_fs(input_path);
        output_path = input_fs.parent_path().string() + "/" + input_fs.stem().string() + ".ply";
    }
    
    std::cout << "Input SOG:  " << input_path << std::endl;
    std::cout << "Output PLY: " << output_path << std::endl << std::endl;
    
    // Check input file exists
    if (!std::filesystem::exists(input_path)) {
        std::cerr << "Error: Input file does not exist: " << input_path << std::endl;
        return 1;
    }
    
    // Read SOG file
    std::cout << "Reading SOG file..." << std::endl;
    tinysog::ReaderOptions read_opts;
    read_opts.cpu_only = true;  // Read to CPU for easier processing
    
    auto result = tinysog::read_sog(input_path.c_str(), read_opts);
    if (!result) {
        std::cerr << "Failed to read SOG: " << result.error() << std::endl;
        return 1;
    }
    
    auto data = result.value();
    
    std::cout << std::endl;
    std::cout << "Statistics:" << std::endl;
    std::cout << "  Point count: " << data.count << std::endl;
    std::cout << "  SH degree:   " << data.sh_degree << std::endl;
    std::cout << "  SH coeffs:   " << data.sh_num_coeffs << std::endl;
    std::cout << std::endl;
    
    // Write PLY file
    std::cout << "Writing PLY file..." << std::endl;
    if (!write_ply(output_path, data)) {
        std::cerr << "Failed to write PLY file" << std::endl;
        tinysog::free_gaussian_data(data);
        return 1;
    }
    
    std::cout << "Successfully wrote PLY file!" << std::endl;
    
    // Get file sizes
    auto input_size = std::filesystem::file_size(input_path);
    auto output_size = std::filesystem::file_size(output_path);
    
    std::cout << std::endl;
    std::cout << "File sizes:" << std::endl;
    std::cout << "  Input SOG:  " << (input_size / 1024.0 / 1024.0) << " MB" << std::endl;
    std::cout << "  Output PLY: " << (output_size / 1024.0 / 1024.0) << " MB" << std::endl;
    std::cout << "  Compression ratio: " << (100.0 * input_size / output_size) << "%" << std::endl;
    std::cout << std::endl;
    
    // Cleanup
    tinysog::free_gaussian_data(data);
    
    std::cout << "Conversion completed successfully!" << std::endl;
    
    return 0;
}

